// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 initialBalance, address recipient) public {
        vm.assume(initialBalance > 0);
        vm.assume(initialBalance <= address(c).balance + initialBalance);

        vm.deal(address(c), initialBalance);

        vm.assume(recipient != address(0));
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(c));

        uint256 balanceBefore = recipient.balance;
        uint256 contractBalanceBefore = address(c).balance;

        c.withdrawAll(recipient);

        uint256 balanceAfter = recipient.balance;
        uint256 contractBalanceAfter = address(c).balance;

        assertTrue(
            balanceAfter == balanceBefore + contractBalanceBefore &&
            contractBalanceAfter == 0
        );
    }
}
